var oldDialogs = app.displayDialogs;
app.displayDialogs = DialogModes.NO;                 // no modal dialogs in a batch
app.open(new File("C:/in/product.jpg"));
app.doAction("Web Export", "Brand Actions");        // names are case-sensitive
app.runMenuItem(app.stringIDToTypeID("fitOnScreen"));
app.purge(PurgeTarget.HISTORYCACHES);
app.displayDialogs = oldDialogs;

var doc = app.activeDocument;
var copy = doc.duplicate("web copy");
copy.resizeImage(UnitValue(1080, "px"), undefined, 72, ResampleMethod.BICUBICSHARPER);
copy.flatten();
var jpg = new JPEGSaveOptions(); jpg.quality = 10;
copy.saveAs(new File("C:/out/post_1080.jpg"), jpg, true);
copy.close(SaveOptions.DONOTSAVECHANGES);
